<?php

namespace Database\Seeders;

use App\Models\AdvancePayment;
use App\Models\AttendanceMonth;
use App\Models\AttendanceRecord;
use App\Models\Company;
use App\Models\Designation;
use App\Models\Employee;
use App\Models\EmployeeProjectAssignment;
use App\Models\ExtraDuty;
use App\Models\Project;
use Illuminate\Database\Seeder;

class EmployeeReferenceSeeder extends Seeder
{
    public function run(): void
    {
        // Generated from the provided Advance Sheet 2025 and February 2026 WADI SAFAR timesheet.
        // Unique employees: 537 | advance rows: 310 | attendance records: 6972 | Friday extra-duty rows: 102.
        $companies = [];
        foreach ($this->companies() as $name) {
            $companies[$name] = Company::firstOrCreate(['name' => $name], ['type' => str_contains(strtolower($name), 'cairo') ? 'manpower' : 'subcontractor']);
        }

        $projects = [];
        foreach ($this->projects() as $name) {
            $projects[$name] = Project::firstOrCreate(['name' => $name], ['status' => 'active']);
        }

        $designations = [];
        foreach ($this->designations() as $name) {
            $designations[$name] = Designation::firstOrCreate(['name' => $name]);
        }

        $employeeIds = [];
        foreach ($this->employees() as $row) {
            $designation = $row['designation'] ? ($designations[$row['designation']] ?? Designation::firstOrCreate(['name' => $row['designation']])) : null;
            $company = $row['company'] ? ($companies[$row['company']] ?? Company::firstOrCreate(['name' => $row['company']])) : null;
            $project = $row['project'] ? ($projects[$row['project']] ?? Project::firstOrCreate(['name' => $row['project']], ['status' => 'active'])) : null;
            $employee = Employee::where('employee_code', $row['employee_code'])->first();
            if (! $employee && ! empty($row['iqama_no'])) {
                $employee = Employee::where('iqama_no', $row['iqama_no'])->first();
            }
            if (! $employee) {
                $employee = Employee::where('normalized_name', Employee::normalizeName($row['name']))->where('designation_id', $designation?->id)->first();
            }

            $employee = Employee::updateOrCreate(
                ['id' => $employee?->id],
                [
                    'employee_code' => $row['employee_code'],
                    'name' => $row['name'],
                    'iqama_no' => $row['iqama_no'],
                    'passport_no' => $row['passport_no'],
                    'designation_id' => $designation?->id,
                    'company_id' => $company?->id,
                    'current_project_id' => $project?->id,
                    'shift' => $row['shift'],
                    'accommodation' => $row['accommodation'],
                    'doj' => $row['doj'],
                    'hourly_rate' => $row['hourly_rate'],
                    'monthly_salary' => $row['monthly_salary'],
                    'status' => $row['status'],
                    'remarks' => $row['remarks'],
                    'source_sheet' => $row['source_sheet'],
                ]
            );
            $employeeIds[$row['employee_code']] = $employee->id;

            if ($project) {
                EmployeeProjectAssignment::updateOrCreate(
                    ['employee_id' => $employee->id, 'project_id' => $project->id, 'end_date' => null],
                    ['status' => 'active', 'remarks' => 'Seeded from compared Excel reference data']
                );
            }
        }

        AttendanceMonth::updateOrCreate(['project_id' => $projects['WADI SAFAR']->id ?? null, 'month' => 2, 'year' => 2026], ['source_file' => '02,FEBRUARY 2026- TIMESHEET WADI SAFAR PROJECT.xlsx', 'source_sheet' => 'FEB 2026', 'imported_at' => now()]);

        foreach ($this->advances() as $row) {
            if (empty($employeeIds[$row['employee_code']])) { continue; }
            $project = $row['project'] ? Project::firstOrCreate(['name' => $row['project']], ['status' => 'active']) : null;
            AdvancePayment::updateOrCreate(
                ['employee_id' => $employeeIds[$row['employee_code']], 'project_id' => $project?->id, 'amount' => $row['amount'], 'payment_date' => $row['payment_date'], 'source_sheet' => $row['source_sheet']],
                ['payment_type' => $row['payment_type'], 'remarks' => $row['remarks']]
            );
        }

        foreach ($this->attendanceRecords() as $row) {
            if (empty($employeeIds[$row['employee_code']])) { continue; }
            $project = $row['project'] ? Project::firstOrCreate(['name' => $row['project']], ['status' => 'active']) : null;
            AttendanceRecord::updateOrCreate(
                ['employee_id' => $employeeIds[$row['employee_code']], 'attendance_date' => $row['attendance_date'], 'project_id' => $project?->id],
                [
                    'month' => $row['month'],
                    'year' => $row['year'],
                    'status' => $row['status'],
                    'hours' => $row['hours'],
                    'raw_value' => $row['raw_value'],
                    'is_extra_duty' => $row['is_extra_duty'],
                    'extra_duty_type' => $row['extra_duty_type'],
                    'extra_duty_hours' => $row['extra_duty_hours'],
                    'extra_duty_amount' => $row['extra_duty_amount'],
                    'remarks' => $row['remarks'],
                    'source_sheet' => $row['source_sheet'],
                ]
            );
        }

        foreach ($this->extraDuties() as $row) {
            if (empty($employeeIds[$row['employee_code']])) { continue; }
            $project = $row['project'] ? Project::firstOrCreate(['name' => $row['project']], ['status' => 'active']) : null;
            ExtraDuty::updateOrCreate(
                ['employee_id' => $employeeIds[$row['employee_code']], 'project_id' => $project?->id, 'duty_date' => $row['duty_date'], 'day_type' => $row['day_type']],
                [
                    'hours_worked' => $row['hours_worked'],
                    'rate' => $row['rate'],
                    'amount' => $row['amount'],
                    'approval_status' => $row['approval_status'],
                    'approved_at' => now(),
                    'remarks' => $row['remarks'],
                    'source_sheet' => $row['source_sheet'],
                ]
            );
        }
    }

